export function clamp(x, lo, hi) {
  if (lo > hi) throw new RangeError(`clamp: lo (${lo}) > hi (${hi})`);
  return Math.min(Math.max(x, lo), hi);
}
import assert from "node:assert/strict";
import { test } from "node:test";
import { clamp } from "../src/clamp.mjs";

test("значение ниже диапазона возвращает lo", () => assert.equal(clamp(-5, 0, 10), 0));
test("значение выше диапазона возвращает hi", () => assert.equal(clamp(15, 0, 10), 10));
test("значение внутри диапазона не меняется", () => assert.equal(clamp(7, 0, 10), 7));
test("нижняя граница возвращается как есть", () => assert.equal(clamp(0, 0, 10), 0));
test("верхняя граница возвращается как есть", () => assert.equal(clamp(10, 0, 10), 10));
test("lo === hi возвращает эту границу", () => assert.equal(clamp(3, 5, 5), 5));
test("lo > hi бросает RangeError", () => assert.throws(() => clamp(1, 10, 0), RangeError));

